package com.example.starter.lot.api;

import com.example.starter.lot.domain.LotStatus;

import java.math.BigDecimal;
import java.util.List;

/**
 * 批次视图。
 *
 * @param lotId                   批次 ID
 * @param unit                    计量单位
 * @param initialQty              初始/产出数量
 * @param consumedQty             累计已消费数量
 * @param availableQty            可用余额 = 初始数量 - 累计消费
 * @param status                  当前状态
 * @param version                 乐观锁版本
 * @param activeQuarantineSources 当前仍生效的隔离来源批次 ID 集合（空表示无隔离）
 */
public record LotResponse(
        String lotId,
        String unit,
        BigDecimal initialQty,
        BigDecimal consumedQty,
        BigDecimal availableQty,
        LotStatus status,
        int version,
        List<String> activeQuarantineSources
) {
}

package com.example.starter.lot.api;

import com.example.starter.lot.domain.LotStatus;

import java.math.BigDecimal;
import java.util.List;

/**
 * 转换结果。
 *
 * @param requestId   幂等请求键
 * @param conversionId 转换单 ID
 * @param unit        计量单位
 * @param inputs      实际记账的父批次消费明细
 * @param outputs     实际记账的子批次产出明细
 * @param totalInputQty  总消费量
 * @param totalOutputQty 总产出量
 * @param loss        实际损耗 = 总消费 - 总产出
 * @param allowedLoss 本次允许损耗
 * @param children    新子批次提交后的状态（可能因已先提交的隔离来源而立即被隔离）
 */
public record ConversionResponse(
        String requestId,
        long conversionId,
        String unit,
        List<ConversionRequest.InputItem> inputs,
        List<ConversionRequest.OutputItem> outputs,
        BigDecimal totalInputQty,
        BigDecimal totalOutputQty,
        BigDecimal loss,
        BigDecimal allowedLoss,
        List<ChildStatus> children
) {

    /**
     * 新子批次提交后状态。
     *
     * @param lotId                     子批次 ID
     * @param status                    状态
     * @param activeQuarantineSources   提交时生效的隔离来源（包含先于本转换提交的祖先隔离）
     */
    public record ChildStatus(String lotId, LotStatus status, List<String> activeQuarantineSources) {
    }
}

package com.example.starter.lot.api;

import com.example.starter.lot.domain.LotStatus;

import java.util.List;

/**
 * 隔离/解除结果。
 *
 * @param sourceLotId 被直接操作的批次（隔离来源）
 * @param action      QUARANTINE / RELEASE
 * @param affected    受本次提交影响的批次及其提交后状态与生效来源集合
 */
public record QuarantineResponse(
        String sourceLotId,
        QuarantineRequest.Action action,
        List<AffectedLot> affected
) {

    /**
     * 受影响批次视图。
     *
     * @param lotId                   批次 ID
     * @param status                  本次提交后的状态
     * @param activeQuarantineSources 当前仍生效的隔离来源集合
     */
    public record AffectedLot(String lotId, LotStatus status, List<String> activeQuarantineSources) {
    }
}

